import {clamp} from './math.mjs';
import {range,button,asset} from './core.mjs';
import {intersectionSolid,apparatusRenderer,lightBasis} from './shadow-apparatus.mjs';

export async function create(stage,controls) {
  const chapters=JSON.parse(document.querySelector('#shadow-chapters').textContent);
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const solid=intersectionSolid(),renderer=apparatusRenderer(solid);
  const theater=document.querySelector('.theater'),hero=document.querySelector('.hero-copy');
  let chapterIndex=0,angle=0,orbit=.71,scan=!reduced.matches,scanDirection=1,target=null,travelFrom=0,travelTime=0;
  let rays=true,dragging=false;
  const travelSeconds=2.4;
  const edition=document.createElement('div');edition.className='shadow-edition';
  edition.innerHTML='<span>半影 <b>PENUMBRA</b></span><small>光与形的机关 / OPTICAL APPARATUS 07</small>';theater.append(edition);
  const folio=document.createElement('aside');folio.className='shadow-folio';folio.setAttribute('aria-label','本章设计札记');
  folio.innerHTML='<small></small><h2></h2><p></p>';theater.append(folio);
  const readout=document.createElement('div');readout.className='shadow-readout';
  readout.innerHTML='<span>LIGHT AZIMUTH</span><strong><b>00.0</b><i>°</i></strong><small>光源沿轨道移动</small>';theater.append(readout);
  const legend=document.createElement('div');legend.className='shadow-legend';
  legend.innerHTML='<span><i></i> LIVE SHADOW</span><small>拖动舞台移动光源 · ↑ ↓ 调整视角</small>';theater.append(legend);
  const notes=document.createElement('details');notes.className='shadow-notes';
  notes.innerHTML='<summary>本章札记 <span>FIELD NOTES ↗</span></summary><div><img alt=""><section><small></small><h2></h2><p></p><p class="shadow-observation"></p></section></div>';
  document.querySelector('.stage').after(notes);
  const status=document.querySelector('#status');folio.append(status);
  document.querySelector('.telemetry').hidden=true;
  hero.setAttribute('aria-live','polite');hero.setAttribute('aria-atomic','true');
  stage.canvas.setAttribute('aria-label','光影机关。左右拖动或左右方向键移动光源，上下方向键调整视角。');
  document.querySelector('.instrument-title strong').textContent='光影机关';
  document.querySelector('.instrument-title > span').textContent='LIGHT TABLE / 07';
  document.querySelector('#snapshot').textContent='保存机关';
  function sync(){
    input.value=String(angle*180/Math.PI);orbitInput.value=String(Math.round(orbit*180/Math.PI));
    scanButton.setAttribute('aria-pressed',String(scan));scanButton.textContent=scan?'停止扫描':'扫描光源';
    rayButton.setAttribute('aria-pressed',String(rays));
    readout.querySelector('b').textContent=(angle*180/Math.PI).toFixed(1).padStart(4,'0');
    readout.querySelector('small').textContent=target!==null?'灯架正在移向本章光位':scan&&stage.playing?'光源沿轨道扫描':'拖动舞台，改变光的方向';
  }
  function manualLight(degrees){angle=clamp(degrees,0,90)*Math.PI/180;target=null;scan=false;sync();stage.dirty=true;}
  const input=range(controls,'光源方位',0,90,0,.1,manualLight);
  button(controls,'对齐月影 · 0°',()=>manualLight(0));
  button(controls,'对齐菱影 · 90°',()=>manualLight(90));
  const orbitInput=range(controls,'观察雕塑',22,68,41,1,v=>{orbit=v*Math.PI/180;stage.dirty=true;});
  const scanButton=button(controls,'停止扫描',()=>{scan=!scan;target=null;if(scan&&!stage.playing)stage.setPlaying(true);sync();stage.dirty=true;});
  const rayButton=button(controls,'光路',()=>{rays=!rays;sync();stage.dirty=true;});
  function writeCopy(){
    const chapter=chapters[chapterIndex];document.body.dataset.chapter=chapter.id;
    document.body.style.setProperty('--accent',chapter.accent);
    hero.querySelector('.eyebrow').textContent=chapter.kicker;
    [...hero.querySelector('h1').children].forEach((line,i)=>line.textContent=chapter.headline[i]);
    hero.querySelector('p').textContent=chapter.body;
    document.querySelector('#interact > span').textContent='移动光源，寻找另一种轮廓';
    folio.querySelector('small').textContent='OBSERVATION / '+String(chapterIndex+1).padStart(2,'0');
    folio.querySelector('h2').textContent=chapter.experiment;
    folio.querySelector('p').textContent=chapter.observation;
    const img=notes.querySelector('img');img.src=asset(chapter.image);img.alt=chapter.alt;
    notes.querySelector('section small').textContent=chapter.material+' / CONCEPT ART';
    notes.querySelector('h2').textContent=chapter.feature;notes.querySelector('section p').textContent=chapter.detail;
    notes.querySelector('.shadow-observation').textContent=chapter.note;
    stage.status('铜质实体 · 平行光 · 实时投影');
  }
  function select(index,{animate=true}={}){
    chapterIndex=(index+chapters.length)%chapters.length;scan=false;
    const next=chapters[chapterIndex].angle*Math.PI/180;
    if(animate&&stage.playing&&!reduced.matches){travelFrom=angle;target=next;travelTime=0;}
    else{angle=next;target=null;}
    writeCopy();sync();stage.dirty=true;
  }
  const scenes={label:'FOUR LIGHT POSITIONS',kind:'LIGHT',items:chapters.map((chapter,index)=>({...chapter,apply:()=>select(index),active:()=>chapterIndex===index}))};
  writeCopy();sync();
  const motionChange=()=>{if(reduced.matches){scan=false;target=null;}sync();stage.dirty=true;};
  reduced.addEventListener('change',motionChange);
  return {
    scenes,interact(){manualLight(angle<Math.PI/4?90:0);},
    reset(){orbit=.71;select(chapterIndex,{animate:false});},
    key(key){if(key==='ArrowRight')manualLight(angle*180/Math.PI+3);if(key==='ArrowLeft')manualLight(angle*180/Math.PI-3);
      if(key==='ArrowUp'||key==='ArrowDown'){orbit=clamp(orbit+(key==='ArrowUp'?.05:-.05),22*Math.PI/180,68*Math.PI/180);sync();}},
    pointer(p){if(p.down){if(dragging)manualLight(angle*180/Math.PI+p.dx*110);dragging=true;}},
    release(){dragging=false;},
    visibility(){sync();},
    render(dt){
      if(dt&&!reduced.matches){
        if(target!==null){travelTime+=dt;const t=clamp(travelTime/travelSeconds),ease=t*t*(3-2*t);angle=travelFrom+(target-travelFrom)*ease;if(t===1)target=null;}
        else if(scan){angle+=scanDirection*dt*.15;if(angle>=Math.PI/2){angle=Math.PI/2;scanDirection=-1;}if(angle<=0){angle=0;scanDirection=1;}}
      }
      sync();renderer.draw(stage.ctx,stage.width,stage.height,angle,orbit,{rays,labels:stage.width>640});
    },
    inspect:()=>({angle,orbit,faces:solid.faces.length,model:'fixed-intersection-solid',renderer:'textured-3d-optical-bench',
      chapter:chapters[chapterIndex].id,scan,rays,target,transition:target===null?1:clamp(travelTime/travelSeconds),
      light:lightBasis(angle).direction,geometryVertices:solid.rings.length*4,...renderer.inspect()}),
    dispose(){reduced.removeEventListener('change',motionChange);},
  };
}
/* PENUMBRA — a working light table. */
