import {add,sub,mul,dot,cross,unit,face,box,camera,imageQuad,renderFaces} from './math.mjs';
import {offscreen} from './core.mjs';

// Fixed intersection of a crescent extrusion (XY) and a diamond extrusion (ZY).
export function intersectionSolid(rows=112) {
  const rings=[],faces=[],radius=Math.sqrt(.91);
  for(let i=0;i<=rows;i++){
    const y=(-1+2*i/rows)*(radius-.00001),outer=Math.sqrt(.91-y*y),inner=.73**2-(y-.10)**2;
    const left=-outer,right=inner>0?Math.min(outer,.39-Math.sqrt(inner)):outer,depth=.98-Math.abs(y);
    rings.push([[left,y,-depth],[right,y,-depth],[right,y,depth],[left,y,depth]]);
  }
  for(let i=0;i<rows;i++)for(let j=0;j<4;j++){
    const k=(j+1)%4;faces.push(face([rings[i][j],rings[i+1][j],rings[i+1][k],rings[i][k]],'#b89151'));
  }
  faces.push(face(rings[0],'#b89151'),face([...rings[rows]].reverse(),'#b89151'));
  return {faces,rings};
}
export function lightBasis(angle) {
  return {direction:[Math.sin(angle),0,Math.cos(angle)],right:[Math.cos(angle),0,-Math.sin(angle)]};
}
export function projectShadow(point,angle,distance=2.65) {
  const {direction}=lightBasis(angle);return sub(point,mul(direction,dot(point,direction)+distance));
}
function cylinder(center,radius,height,color,segments=48) {
  const bottom=[],top=[],faces=[];
  for(let i=0;i<segments;i++){
    const a=i/segments*Math.PI*2,p=[Math.cos(a)*radius,0,Math.sin(a)*radius];
    bottom.push(add(center,add(p,[0,-height/2,0])));top.push(add(center,add(p,[0,height/2,0])));
  }
  for(let i=0;i<segments;i++){const j=(i+1)%segments;faces.push(face([bottom[i],top[i],top[j],bottom[j]],color));}
  faces.push(face(bottom,color),face([...top].reverse(),color));return faces;
}
function grainTexture(base,size=256,brushed=false) {
  const c=offscreen(size,size),ctx=c.getContext('2d'),pixels=ctx.createImageData(size,size);let seed=718;
  for(let y=0;y<size;y++)for(let x=0;x<size;x++){
    seed=(Math.imul(seed,1664525)+1013904223)>>>0;
    const i=(y*size+x)*4,n=(seed/4294967296-.5)*13+(brushed?Math.sin(y*1.7)*4:0);
    for(let k=0;k<3;k++)pixels.data[i+k]=Math.max(0,Math.min(255,base[k]+n));pixels.data[i+3]=255;
  }
  ctx.putImageData(pixels,0,0);return c;
}

// Opaque meshes use a depth buffer. The existing Canvas projection is retained
// as a fallback for browsers without WebGL2 or after a lost GPU context.
function gpuSurface(brass,slate,receiver) {
  const canvas=offscreen(1,1),gl=canvas.getContext('webgl2',{alpha:true,antialias:true,premultipliedAlpha:false});
  if(!gl)return null;
  const compile=(type,source)=>{const shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(shader));return shader;};
  const program=gl.createProgram();
  gl.attachShader(program,compile(gl.VERTEX_SHADER,`#version 300 es
    precision highp float;
    layout(location=0) in vec3 position;
    layout(location=1) in vec3 normal;
    layout(location=2) in vec2 uv;
    layout(location=3) in vec3 color;
    layout(location=4) in float material;
    uniform vec3 eye,forward,right,up;
    uniform vec2 projection;
    out vec3 N,P,C;
    out vec2 UV;
    flat out int M;
    void main(){vec3 q=position-eye;float z=dot(q,forward);
      gl_Position=vec4(dot(q,right)*projection.x,dot(q,up)*projection.y,1.00160128*z-.1601281,z);
      N=normal;P=position;UV=uv;C=color;M=int(material+.5);
    }`));
  gl.attachShader(program,compile(gl.FRAGMENT_SHADER,`#version 300 es
    precision highp float;
    in vec3 N,P,C;
    in vec2 UV;
    flat in int M;
    uniform sampler2D bronze,stone,screen;
    uniform vec3 light,eye;
    out vec4 outColor;
    void main(){
      vec3 n=normalize(N),l=normalize(light),v=normalize(eye-P);
      float diffuse=max(0.,dot(n,l)),spec=pow(max(0.,dot(n,normalize(l+v))),38.);
      vec3 c=C;
      if(M==1){c=texture(bronze,UV).rgb*(.3+.77*diffuse)+vec3(1.,.85,.53)*spec*.55;}
      else if(M==2){c=texture(stone,UV).rgb;}
      else if(M==3){c=texture(screen,UV).rgb;}
      else if(M==0){c*=.42+.58*max(0.,dot(n,l));}
      outColor=vec4(c,M==4?UV.x:1.);
    }`));
  gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));
  gl.useProgram(program);const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);
  const stride=12*4;
  for(const [loc,size,offset] of [[0,3,0],[1,3,3],[2,2,6],[3,3,8],[4,1,11]]){gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,stride,offset*4);}
  const uniforms=Object.fromEntries(['eye','forward','right','up','projection','light'].map(name=>[name,gl.getUniformLocation(program,name)]));
  const textures=[brass,slate,receiver].map((source,i)=>{
