import assert from 'node:assert/strict';
import {intersectionSolid,lightBasis,projectShadow} from '../src/studies/shadow-apparatus.mjs';
import {dot,sub,cross} from '../src/studies/math.mjs';

const solid=intersectionSolid(),before=JSON.stringify(solid),tests=[];
function test(name,run){run();tests.push(name);console.log('PASS',name);}
const near=(a,b,epsilon=1e-9)=>assert.ok(Math.abs(a-b)<epsilon,`${a} != ${b}`);
test('closed solid has finite vertices and two faces per edge',()=>{
  const edges=new Map();
  for(const {points} of solid.faces)for(let i=0;i<points.length;i++){
    assert.ok(points[i].every(Number.isFinite));
    const edge=[points[i].join(','),points[(i+1)%points.length].join(',')].sort().join('|');
    edges.set(edge,(edges.get(edge)||0)+1);
  }
  assert.ok([...edges.values()].every(n=>n===2));
});
test('front projection follows the crescent extrusion',()=>{
  for(const ring of solid.rings){
    const y=ring[0][1],outer=Math.sqrt(.91-y*y),inner=.73**2-(y-.1)**2;
    const projected=ring.map(p=>projectShadow(p,0));
    near(Math.min(...projected.map(p=>p[0])),-outer);
    near(Math.max(...projected.map(p=>p[0])),inner>0?Math.min(outer,.39-Math.sqrt(inner)):outer);
  }
});
test('side projection follows the diamond extrusion',()=>{
  for(const ring of solid.rings){
    const projected=ring.map(p=>projectShadow(p,Math.PI/2));
    near(Math.max(...projected.map(p=>p[2])),.98-Math.abs(ring[0][1]));
    near(Math.min(...projected.map(p=>p[2])),-.98+Math.abs(ring[0][1]));
  }
});
test('every intermediate ray lands on its linked receiver plane',()=>{
  for(let degrees=0;degrees<=90;degrees+=3){
    const angle=degrees*Math.PI/180,{direction,right}=lightBasis(angle);
    for(const ring of solid.rings)for(const p of ring){
      const q=projectShadow(p,angle);
      near(dot(q,direction),-2.65);near(dot(q,right),dot(p,right));near(q[1],p[1]);
      cross(sub(q,p),direction).forEach(n=>near(n,0));
    }
  }
});
test('small light motion produces continuous shadow travel',()=>{
  for(let angle=0;angle<Math.PI/2;angle+=.02)for(const p of solid.rings[57]){
    const a=projectShadow(p,angle),b=projectShadow(p,angle+.0001);
    assert.ok(Math.hypot(...sub(a,b))<.0005);
  }
});
test('projection never mutates the modeled object',()=>assert.equal(JSON.stringify(solid),before));
console.log(`${tests.length} shadow geometry tests passed.`);
