import json
from pathlib import Path
p=Path('src/studies/catalog.json')
s=p.read_text(encoding='utf-8')
items=json.loads(s)
c=next(x for x in items if x['id']=='shadow')
c.update(line='三束光穿过同一片空间，文字与影像在青、绯、金之间，留下各自的回声。',help='拖动展场改变光的方向。底栏选择四章，空格暂停；调光可改变方向、浓度与自动换章。',mechanism='半影 PENUMBRA 是一组空间诗。铜色文字、原画与三束异色光共享整面展场。四章依次展现轮廓、边界、层次与回望，影子从不同方向穿过字与图，在同一平面相遇。',limits='原画沿用四张 AI 光影概念图。浮字与影像使用升起的平面和点光源投影，字体表面为程序生成的铜色纹理；呈现为艺术化空间排版。',headline1='让光穿过，',headline2='让影留下。',action='下一篇 · 边界的温度',medium='THREE LIGHTS / FOUR POEMS',signature='PENUMBRA / SPATIAL ANTHOLOGY')
updates=[
 dict(display='半影',headline=['让光穿过，','让影留下。'],body='一弯铜月，一片微光。青色从远处抵达，绯色擦过边缘，金色在文字下方停住。你走进来，影子便有了新的方向。',detail='月牙悬在暗处，字浮在光里。两道轮廓擦肩而过，留下第三种形状。',feature='在静默中，听见回声',action='下一篇 · 边界的温度'),
 dict(display='边界',headline=['光止于此，','故事向外。'],body='暖墙上的一条亮边，把两个世界轻轻分开。深处的青与近处的绯交叠，明暗之间，还容得下一次回望。',detail='把光留在边缘，让影越过边缘。曲面的一线微亮，接住了整个房间的呼吸。',feature='明暗相接的地方',action='下一篇 · 深处的秩序'),
 dict(display='深处',headline=['一层远方，','一层回响。'],body='薄片彼此错开，微光沿着缝隙穿行。前面的影子往左，后面的影子向右，视线顺着它们，在平面里走向深处。',detail='七片铜，七次停顿。眼前的线条退后一步，藏起的面便渐渐浮出。',feature='层叠之间，自有秩序',action='下一篇 · 第二种答案'),
 dict(display='回望',headline=['换个方向，','再看一眼。'],body='金色的菱面停在半空。来时看过的字，此刻投下另一道影。光仍在缓缓转动，空间替你保留了一次新的相遇。',detail='展览走到末尾，影子又回到开头。把那个未看清的角度，留给下一次经过。',feature='转身之后，光还在',action='重新翻阅 · 轮廓的开场')]
for chapter,u in zip(c['chapters'],updates): chapter.update(u)
a=s.index('  {\\n    \"id\": \"shadow\"')
b=s.index('\\n  {\\n    \"id\": \"folding\"',a)
s=s[:a]+''.join('  '+line+'\\n' for line in json.dumps(c,ensure_ascii=False,indent=2).splitlines()).rstrip()+',\\n'+s[b:]
p.write_text(s,encoding='utf-8')
